import java.util.Deque;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedDeque;

import org.springframework.stereotype.Component;

/**
 * Keeps every message sent through the contact form for the lifetime of the application.
 */
@Component
public class MessageStore {

    private final Deque<ContactMessage> messages = new ConcurrentLinkedDeque<>();

    public void add(ContactMessage message) {
        messages.addFirst(message);
    }

    /**
     * @return all sent messages, newest first
     */
    public List<ContactMessage> findAllNewestFirst() {
        return List.copyOf(messages);
    }
}
