import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.microsoft.playwright.Browser;
import com.microsoft.playwright.BrowserType;
import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.Playwright;
import com.microsoft.playwright.options.AriaRole;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class ContactViewBrowserTest {

    @LocalServerPort
    private int port;

    private static Playwright playwright;
    private static Browser browser;

    @BeforeAll
    static void startBrowser() {
        playwright = Playwright.create();
        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(true));
    }

    @AfterAll
    static void stopBrowser() {
        browser.close();
        playwright.close();
    }

    @Test
    void contactPageLoadsAndSendsAMessage() {
        try (Page page = browser.newPage()) {
            page.navigate("http://localhost:" + port + "/contact");
            page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("Contact")).waitFor();

            Locator send = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"));
            page.getByLabel("Name").fill("Browser Tester");
            page.getByLabel("Email").fill("browser@example.com");
            page.getByLabel("Message").fill("Hello from a browser");
            send.click();

            Locator notification = page.locator("vaadin-notification-card");
            notification.first().waitFor();
            assertTrue(notification.first().textContent().contains("Message sent"));
            assertEquals("", page.getByLabel("Name").inputValue());
            assertTrue(send.isDisabled());
        }
    }
}
