+package com.example.views;
+
+import java.util.regex.Pattern;
+
+import com.example.service.ContactMessage;
+import com.example.service.MessageStore;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final MessageStore messageStore;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction continueNavigation;
+
+    /** True while the application itself empties the fields, so that doesn't count as an edit. */
+    private boolean clearing;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(e -> onEdit());
+        email.addValueChangeListener(e -> onEdit());
+        phone.addValueChangeListener(e -> onEdit());
+        message.addValueChangeListener(e -> onEdit());
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setColspan(message, 2);
+
+        send.addClickListener(e -> sendIfEnabled());
+        Shortcuts.addShortcutListener(this, this::sendIfEnabled, Key.ENTER);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setAllRowsVisible(true);
+        grid.setItems(messageStore.findAllNewestFirst());
+
+        configureLeaveDialog();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, grid, leaveDialog);
+    }
+
+    private void configureLeaveDialog() {
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Paragraph("You have typed something that has not been sent yet. "
+                + "If you leave now, it will be lost."));
+
+        Button keepEditing = new Button("Keep editing", e -> {
+            leaveDialog.close();
+            cancelNavigation();
+        });
+        Button discard = new Button("Discard", e -> {
+            leaveDialog.close();
+            proceedNavigation();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+        leaveDialog.addDialogCloseActionListener(e -> cancelNavigation());
+    }
+
+    private void cancelNavigation() {
+        if (continueNavigation != null) {
+            continueNavigation.cancel();
+            continueNavigation = null;
+        }
+    }
+
+    private void proceedNavigation() {
+        if (continueNavigation != null) {
+            continueNavigation.proceed();
+            continueNavigation = null;
+        }
+    }
+
+    private void onEdit() {
+        if (!clearing) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void sendIfEnabled() {
+        if (send.isEnabled()) {
+            sendMessage();
+        }
+    }
+
+    private void sendMessage() {
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+
+        String nameError = nameValue.isEmpty() ? "Name is required" : null;
+
+        String emailError = null;
+        if (!emailValue.isEmpty()) {
+            if (!EMAIL_PATTERN.matcher(emailValue).matches()) {
+                emailError = "Enter a valid e-mail address";
+            }
+        } else if (phoneValue.isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+
+        String messageError = null;
+        if (messageValue.isEmpty()) {
+            messageError = "Message is required";
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+
+        mark(name, nameError);
+        mark(email, emailError);
+        mark(message, messageError);
+        if (nameError != null || emailError != null || messageError != null) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(nameValue, emailValue, phoneValue, messageValue));
+        Notification.show("Message sent");
+        clearFields();
+        send.setEnabled(false);
+        grid.setItems(messageStore.findAllNewestFirst());
+    }
+
+    private static void mark(HasValidation field, String error) {
+        field.setInvalid(error != null);
+        field.setErrorMessage(error);
+    }
+
+    private void clearFields() {
+        clearing = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearing = false;
+        }
+    }
+
+    private boolean hasUnsentInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsentInput()) {
+            continueNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+}
